#include <string>
#include <unordered_set>

class Solution {
public:
    bool checkGoodInteger(long long n) {
        std::string s = std::to_string(n);
        std::unordered_set<char> seen(s.begin(), s.end());
        if (seen.size() != s.size()) return false;
        for (size_t i = 1; i < s.size(); ++i) {
            if ((s[i] - '0') % 2 == (s[i - 1] - '0') % 2) return false;
        }
        return true;
    }
};

import java.util.*;

class Solution {
    public boolean checkGoodInteger(long n) {
        String s = Long.toString(n);
        Set<Character> seen = new HashSet<>();
        for (char c : s.toCharArray()) seen.add(c);
        if (seen.size() != s.length()) return false;
        for (int i = 1; i < s.length(); i++) {
            if ((s.charAt(i) - '0') % 2 == (s.charAt(i - 1) - '0') % 2) return false;
        }
        return true;
    }
}

